DO $$ BEGIN BEGIN INSERT INTO cemetery_occupancy (space_id,person_id,contract_id,started_at,ended_at) VALUES (1,2,1,now(),NULL); RAISE EXCEPTION 'Se admitió doble ocupación del espacio'; EXCEPTION WHEN unique_violation THEN NULL; END; END $$;
DO $$ BEGIN BEGIN INSERT INTO cemetery_occupancy (space_id,person_id,contract_id,started_at,ended_at) VALUES (2,1,2,now(),NULL); RAISE EXCEPTION 'Se admitió doble ubicación de la persona'; EXCEPTION WHEN unique_violation THEN NULL; END; END $$;
DO $$ BEGIN BEGIN INSERT INTO cemetery_reservation (space_id,responsible_id,expires_on,state,reason,created_at) VALUES (3,1,current_date+8,'ACTIVE','',now()); RAISE EXCEPTION 'Se admitió doble reserva activa'; EXCEPTION WHEN unique_violation THEN NULL; END; END $$;
DO $$ BEGIN BEGIN INSERT INTO cemetery_user (password,is_superuser,first_name,last_name,is_staff,is_active,date_joined,email,role) VALUES ('synthetic',false,'','',false,true,now(),'SCHEMA@EXAMPLE.TEST','VIEWER'); RAISE EXCEPTION 'Se admitió un correo duplicado'; EXCEPTION WHEN unique_violation THEN NULL; END; END $$;
DO $$ BEGIN BEGIN INSERT INTO cemetery_payment (contract_id,reservation_id,amount,method,reference,paid_at,created_by_id,voided_at,void_reason) VALUES (1,NULL,-1,'CASH','TEST',now(),1,NULL,''); RAISE EXCEPTION 'Se admitió un pago negativo'; EXCEPTION WHEN check_violation THEN NULL; END; END $$;
DO $$ BEGIN BEGIN INSERT INTO cemetery_contract (number,space_id,responsible_id,reservation_id,amount,currency,starts_on,ends_on,state,terms,created_at) VALUES ('BAD-DATES',4,1,NULL,100,'COP',current_date+1,current_date,'ACTIVE','Prueba',now()); RAISE EXCEPTION 'Se admitió un intervalo contractual inválido'; EXCEPTION WHEN check_violation THEN NULL; END; END $$;
DO $$ BEGIN BEGIN UPDATE cemetery_event SET detail='Alterado' WHERE id=1; RAISE EXCEPTION 'Se permitió modificar historial'; EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'El historial y la auditoría son de solo inserción.' THEN RAISE; END IF; END; END $$;
DO $$ BEGIN BEGIN DELETE FROM cemetery_audit WHERE id=1; RAISE EXCEPTION 'Se permitió borrar auditoría'; EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'El historial y la auditoría son de solo inserción.' THEN RAISE; END IF; END; END $$;
SELECT 'postgres_schema_and_constraints_ok';
